DO $$ DECLARE d text; BEGIN SELECT pg_get_functiondef('public.corrective_regression_checks()'::regprocedure) INTO d; d:=replace(d,'SELECT id INTO cid FROM public.clients ORDER BY created_at LIMIT 1;','SELECT client_id INTO cid FROM public.social_accounts WHERE is_active AND connection_status=''connected'' ORDER BY created_at LIMIT 1;'); EXECUTE d; END $$;
CREATE OR REPLACE FUNCTION public.return_comment_to_queue(_post uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p public.external_posts; BEGIN SELECT * INTO p FROM public.external_posts WHERE id=_post FOR UPDATE; IF NOT public.can_edit_content(auth.uid()) OR NOT public.is_workspace_member(auth.uid()) OR NOT public.user_can_access_client(auth.uid(),p.client_id) THEN RAISE EXCEPTION 'Your role cannot reopen this comment'; END IF; PERFORM set_config('app.delivery_authorized','true',true); UPDATE public.external_posts SET is_commented=false WHERE id=p.id; END $$;
REVOKE ALL ON FUNCTION public.return_comment_to_queue(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.return_comment_to_queue(uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.cancel_delivery_schedule(_post uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p public.post_cards; BEGIN SELECT * INTO p FROM public.post_cards WHERE id=_post FOR UPDATE; IF NOT public.can_edit_content(auth.uid()) OR NOT public.is_workspace_member(auth.uid()) OR NOT public.user_can_access_client(auth.uid(),p.client_id) THEN RAISE EXCEPTION 'Your role cannot cancel this schedule'; END IF; IF p.is_sample OR p.delivery_status<>'scheduled' THEN RAISE EXCEPTION 'Only a pending real schedule can be canceled'; END IF; UPDATE public.delivery_operations SET status='skipped',reason='Schedule canceled',updated_at=now() WHERE post_card_id=p.id AND status='scheduled'; PERFORM set_config('app.delivery_authorized','true',true); UPDATE public.post_cards SET delivery_status='idle',publishing_status='idle',scheduled_for=NULL WHERE id=p.id; END $$;
REVOKE ALL ON FUNCTION public.cancel_delivery_schedule(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.cancel_delivery_schedule(uuid) TO authenticated;
